<template>
  <div v-if="uploadProgress.isUploading" class="flex flex-col gap-2 rounded-xl border bg-card p-4">
    <div class="flex items-center justify-between gap-2 text-sm">
      <span class="flex items-center gap-2 font-medium">
        <CloudUpload class="size-4 shrink-0 animate-pulse" />
        Uploading work shift data…
      </span>
      <span class="text-muted-foreground tabular-nums">{{ percent }}%</span>
    </div>
    <Progress :model-value="percent" />
  </div>
</template>

<script setup lang="ts">
import { CloudUpload } from 'lucide-vue-next';
import { useMobileRuntimeState } from '~/composables/mobile/useMobileRuntimeState';

const { uploadProgress } = useMobileRuntimeState();

const percent = computed(() => {
  const { total, uploaded } = uploadProgress.value;
  if (total <= 0) return 0;
  return Math.min(100, Math.round((uploaded / total) * 100));
});
</script>
