<template>
  <div v-if="isNative && firstRow" class="w-full max-w-md space-y-4">
    <div class="flex items-center justify-between rounded-xl border p-3">
      <div class="space-y-1">
        <div class="font-medium">
          {{ firstRow.label }}
        </div>

        <div class="text-xs text-muted-foreground">
          {{ firstRow.description }}
        </div>
      </div>

      <div class="shrink-0 w-[140px] flex justify-end">
        <Button
          v-if="statuses[firstRow.key]?.status === 'prompt'"
          variant="default"
          class="w-full text-[14px]/[24px] ml-4 h-full"
          @click="onToggle(firstRow.key, true)"
        >
          Allow
        </Button>

        <NuxtLink
          v-else-if="statuses[firstRow.key]?.status === 'denied'"
          :to="{}"
          class="w-full text-right text-[14px]/[24px] text-accent2-foreground whitespace-nowrap"
          @click.prevent="openAppSettings()"
        >
          Go to settings ->
        </NuxtLink>
      </div>
    </div>
  </div>
</template>

<script setup lang="ts">
import { Capacitor } from '@capacitor/core';
import { computed, onMounted } from 'vue';
import {
  useMobilePermissions,
  openAppSettings,
  getRequiredPermissions,
  describePermissionIssue,
} from '~/composables/mobile/useMobilePermissions';
import type { ModuleName } from 'permissions-manager-plugin';
import type { SelectorProjectItem } from '~/client';

const { platform, statuses, granted, refresh, requestOne } = useMobilePermissions();
const isNative = Capacitor.isNativePlatform();

const props = defineProps<{ project: SelectorProjectItem | null | undefined }>();

const rows = computed(() => {
  const required = getRequiredPermissions(platform, props.project ?? null);
  return required
    .map((key) => ({
      key,
      ...describePermissionIssue(platform, key, statuses.value[key]),
      granted: granted.value[key],
    }))
    .filter((r) => !r.granted);
});

const firstRow = computed(() => rows.value[0] ?? null);

async function onToggle(key: ModuleName, on: boolean) {
  if (on) {
    await requestOne(key);
  } else {
    await openAppSettings();
  }
}

onMounted(async () => {
  await refresh();
});
</script>
